// Simple Asteroid Dodge game targeting <canvas id="game"></canvas>
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = canvas.clientWidth;
canvas.height = canvas.clientHeight;

// Ship state
let ship = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  angle: 0,
  radius: 10,
  vx: 0,
  vy: 0,
};

const keys = { left: false, right: false, up: false };

// Asteroid state
let asteroids = [];
let asteroidTimer = 0;
let score = 0;
let startTime = performance.now();
let dodged = 0;

function rand(min, max) { return Math.random() * (max - min) + min; }

function spawnAsteroid() {
  // Choose edge
  const edge = Math.floor(rand(0, 4)); // 0 top,1 right,2 bottom,3 left
  let x, y, vx, vy;
  const speed = rand(0.5, 2);
  switch (edge) {
    case 0: // top
      x = rand(0, canvas.width); y = -20; vx = rand(-1, 1) * speed; vy = speed; break;
    case 1: // right
      x = canvas.width + 20; y = rand(0, canvas.height); vx = -speed; vy = rand(-1, 1) * speed; break;
    case 2: // bottom
      x = rand(0, canvas.width); y = canvas.height + 20; vx = rand(-1, 1) * speed; vy = -speed; break;
    case 3: // left
      x = -20; y = rand(0, canvas.height); vx = speed; vy = rand(-1, 1) * speed; break;
  }
  const radius = rand(10, 30);
  asteroids.push({ x, y, vx, vy, radius });
}

function update(dt) {
  // Ship rotation
  if (keys.left) ship.angle -= 3 * dt;
  if (keys.right) ship.angle += 3 * dt;
  // Thrust
  if (keys.up) {
    const thrust = 100 * dt;
    ship.vx += Math.cos(ship.angle) * thrust;
    ship.vy += Math.sin(ship.angle) * thrust;
  }
  // Apply velocity
  ship.x += ship.vx * dt;
  ship.y += ship.vy * dt;
  // Friction
  ship.vx *= 0.99;
  ship.vy *= 0.99;
  // Screen wrap for ship
  if (ship.x < 0) ship.x += canvas.width;
  if (ship.x > canvas.width) ship.x -= canvas.width;
  if (ship.y < 0) ship.y += canvas.height;
  if (ship.y > canvas.height) ship.y -= canvas.height;

  // Asteroids
  asteroidTimer -= dt;
  if (asteroidTimer <= 0) {
    spawnAsteroid();
    asteroidTimer = rand(0.5, 2);
  }
  for (let i = asteroids.length - 1; i >= 0; i--) {
    const a = asteroids[i];
    a.x += a.vx * dt;
    a.y += a.vy * dt;
    // Remove off‑screen
    if (a.x < -50 || a.x > canvas.width + 50 || a.y < -50 || a.y > canvas.height + 50) {
      asteroids.splice(i, 1);
      dodged++;
    }
  }

  // Collision detection
  for (const a of asteroids) {
    const dx = a.x - ship.x;
    const dy = a.y - ship.y;
    const dist = Math.hypot(dx, dy);
    if (dist < a.radius + ship.radius) {
      // Game over – stop loop by not requesting next frame
      alert(`Game over! Time: ${((performance.now() - startTime) / 1000).toFixed(1)}s, Dodged: ${dodged}`);
      window.location.reload();
      return;
    }
  }

  // Score based on time survived
  score = ((performance.now() - startTime) / 1000).toFixed(1);
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  // Ship (triangle)
  ctx.save();
  ctx.translate(ship.x, ship.y);
  ctx.rotate(ship.angle);
  ctx.beginPath();
  ctx.moveTo(15, 0);
  ctx.lineTo(-10, -7);
  ctx.lineTo(-10, 7);
  ctx.closePath();
  ctx.fillStyle = 'white';
  ctx.fill();
  ctx.restore();

  // Asteroids
  ctx.fillStyle = 'gray';
  for (const a of asteroids) {
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
    ctx.fill();
  }

  // UI
  ctx.fillStyle = 'yellow';
  ctx.font = '16px sans-serif';
  ctx.fillText(`Time: ${score}s`, 10, 20);
  ctx.fillText(`Dodged: ${dodged}`, 10, 40);
}

let last = performance.now();
function loop(now) {
  const dt = (now - last) / 1000; // seconds
  last = now;
  update(dt);
  draw();
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

// Keyboard handling
window.addEventListener('keydown', e => {
  if (e.code === 'ArrowLeft') keys.left = true;
  else if (e.code === 'ArrowRight') keys.right = true;
  else if (e.code === 'ArrowUp') keys.up = true;
});
window.addEventListener('keyup', e => {
  if (e.code === 'ArrowLeft') keys.left = false;
  else if (e.code === 'ArrowRight') keys.right = false;
  else if (e.code === 'ArrowUp') keys.up = false;
});
